def UpperAdmissibleSet (L : ℝ) (s : Finset ℕ) : Prop :=
  ∀ p ∈ s, ¬Even ((s.filter (fun q => p ≤ q)).card) →
    (((s.filter (fun q => p ≤ q)).prod id : ℕ) : ℝ) * (p : ℝ) ^ 2 < L
